from auth import verify_token


def test_matching_tokens():
    assert verify_token('secret-token-123', 'secret-token-123') is True


def test_mismatched_same_length():
    assert verify_token('secret-token-123', 'secret-token-124') is False


def test_different_length_tokens():
    assert verify_token('secret-token-123', 'short') is False
    assert verify_token('short', 'secret-token-123') is False


def test_empty_strings():
    assert verify_token('', '') is True
    assert verify_token('x', '') is False

